export function PresenceAvatarStack({
    people,
    maxVisible = 5,
    size = 24,
    className,
    overflowTitle = 'Mais pessoas no quadro',
}: PresenceAvatarStackProps) {
    const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
    const [openTooltipId, setOpenTooltipId] = useState<string | null>(null);
    const visible = people.slice(0, maxVisible);
    const overflow = people.length - visible.length;
    const useCompactStack = visible.length > 3;
    const overlap = useCompactStack ? Math.round(size * 0.22) : 0;

    const handleLeave = useCallback(() => {
        setHoveredIndex(null);
        setOpenTooltipId(null);
    }, []);

    const handleTooltipOpenChange = useCallback((personId: string, open: boolean) => {
        setOpenTooltipId(open ? personId : null);
    }, []);

    const handleOverflowOpenChange = useCallback((open: boolean) => {
        if (open) {
            setHoveredIndex(null);
            setOpenTooltipId(null);
        }
    }, []);

    const overflowPeople = people.slice(maxVisible);

    if (people.length === 0) return null;

    return (
        <TooltipProvider delayDuration={120}>
            <div
                className={cn('flex items-center overflow-visible py-0.5 pl-0.5', className)}
                onMouseLeave={handleLeave}
            >
                {visible.map((person, index) => (
                    <PresenceAvatarFace
                        key={person.id}
                        person={person}
                        index={index}
                        size={size}
                        overlap={overlap}
                        useCompactStack={useCompactStack}
                        hoveredIndex={hoveredIndex}
                        openTooltipId={openTooltipId}
                        onHover={setHoveredIndex}
                        onLeave={handleLeave}
                        onTooltipOpenChange={handleTooltipOpenChange}
                    />
                ))}
                {overflow > 0 ? (
                    <PresenceOverflowPopover
                        people={overflowPeople}
                        overflowCount={overflow}
                        size={size}
                        overlap={overlap}
                        useCompactStack={useCompactStack}
                        overflowTitle={overflowTitle}
                        onOpenChange={handleOverflowOpenChange}
                    />
                ) : null}
            </div>
        </TooltipProvider>
    );
}

