'use client';

import { ResourcePresenceBar } from '@/components/Collaboration/ResourcePresenceBar';
import { useCollaborationContext } from '@/components/Collaboration/CollaborationContext';

interface CollaborationPresenceFromContextProps {
    label?: string;
    variant?: 'default' | 'compact';
    className?: string;
}

export function CollaborationPresenceFromContext({
    label = 'vendo esta página',
    variant = 'compact',
    className,
}: CollaborationPresenceFromContextProps) {
    const collaboration = useCollaborationContext();

    if (!collaboration || collaboration.displayViewers.length === 0) return null;

    return (
        <ResourcePresenceBar
            variant={variant}
            viewers={collaboration.displayViewers}
            currentUserId={collaboration.currentUserId}
            label={label}
            className={className}
        />
    );
}
